# rsp.s: the RSP microcode the program image carries (generated by gen_data_tree.py). The blobs are the SDK's
# rspboot, gspF3DEX 1.23 and audio (aspMain) microcode, RSP code/DMEM images, not R4300 code. Each .bin is
# BUILD output: assembled by tools/assets/assets.py rspbin from assets/rsp/<game>/*.s (g2's RSP assembly);
# the original build linked them as SDK objects.
    .section .rsp_text, "a"
    .globl rspbootTextStart
rspbootTextStart:
    .incbin "rspboot.bin"
    .globl gspF3DEXTextStart
gspF3DEXTextStart:
    .incbin "gspF3DEX.text.bin"
    .globl aspMainTextStart
aspMainTextStart:
    .incbin "aspMain.text.bin"
    .globl aspMainTextEnd
aspMainTextEnd:
    .section .rsp_data, "a"
    .globl gspF3DEXDataStart
gspF3DEXDataStart:
    .incbin "gspF3DEX.data.bin"
    .globl aspMainDataStart
aspMainDataStart:
    .incbin "aspMain.data.bin"
    .globl aspMainDataEnd
aspMainDataEnd:
